package com.primehr.migration;
import org.flywaydb.core.Flyway;import org.flywaydb.core.api.MigrationVersion;import org.junit.jupiter.api.Test;import java.sql.DriverManager;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class PrimeHrV45ToV46UpgradeTest{
 @Test void populatedEvaluationCaseSurvivesAwardMigration()throws Exception{
  String db="primehr_v46_"+UUID.randomUUID().toString().replace("-","");String url="jdbc:h2:mem:"+db+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1";Map<String,String>p=Map.of("primehrSchema","PUBLIC");Flyway initial=flyway(url,p,"45");initial.migrate();
  try{try(var c=DriverManager.getConnection(url,"sa","");var s=c.createStatement()){
   s.executeUpdate("INSERT INTO PUBLIC.rr_governance_policy(id,agency_id,code,normalized_code,created_by,created_at,updated_by,updated_at) VALUES('policy','A','PRAISE','PRAISE','test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");
   s.executeUpdate("INSERT INTO PUBLIC.rr_governance_policy_version(id,agency_id,policy_id,definition_version,title,legal_basis,policy_reference,committee_required,allows_individual_awards,allows_group_awards,allows_organization_awards,allows_monetary_incentives,allows_nonmonetary_incentives,requires_agency_head_approval,annual_report_required,status,effective_from,published_by,published_at,record_version,created_by,created_at,updated_by,updated_at) VALUES('policy-v1','A','policy',1,'PRAISE','CSC MC','Resolution',TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,TRUE,'PUBLISHED',DATE '2026-01-01','test',CURRENT_TIMESTAMP,0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");
   s.executeUpdate("INSERT INTO PUBLIC.rr_award_category(id,agency_id,code,normalized_code,created_by,created_at,updated_by,updated_at) VALUES('cat','A','AWARD','AWARD','test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");
   s.executeUpdate("INSERT INTO PUBLIC.rr_award_category_version(id,agency_id,category_id,definition_version,title,nominee_type,incentive_type,eligibility_guidance,evidence_requirements,criteria_revision,status,effective_from,published_by,published_at,record_version,created_by,created_at,updated_by,updated_at) VALUES('cv','A','cat',1,'Award','INDIVIDUAL','MONETARY','Eligible','Evidence',0,'PUBLISHED',DATE '2026-01-01','test',CURRENT_TIMESTAMP,0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");
   s.executeUpdate("INSERT INTO PUBLIC.rr_committee_charter(id,agency_id,code,normalized_code,created_by,created_at,updated_by,updated_at) VALUES('charter','A','C','C','test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");
   s.executeUpdate("INSERT INTO PUBLIC.rr_committee_charter_version(id,agency_id,charter_id,definition_version,title,legal_basis,quorum_type,quorum_value,requires_secretariat,requires_agency_head_decision,conflict_declaration_required,roster_revision,status,effective_from,published_by,published_at,record_version,created_by,created_at,updated_by,updated_at) VALUES('chv','A','charter',1,'Committee','CSC MC','COUNT',1,TRUE,TRUE,TRUE,0,'PUBLISHED',DATE '2026-01-01','test',CURRENT_TIMESTAMP,0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");
   s.executeUpdate("INSERT INTO PUBLIC.rr_award_cycle(id,agency_id,code,normalized_code,title,policy_version_id,policy_definition_version,policy_fingerprint,nomination_opens_on,nomination_closes_on,evaluation_opens_on,evaluation_closes_on,decision_due_on,status,record_version,created_by,created_at,updated_by,updated_at) VALUES('cycle','A','2026','2026','Cycle','policy-v1',1,'fp',DATE '2026-01-01',DATE '2026-02-01',DATE '2026-02-01',DATE '2026-03-01',DATE '2026-04-01','OPEN',0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");
   s.executeUpdate("INSERT INTO PUBLIC.rr_nomination(id,agency_id,cycle_id,category_version_id,category_definition_version,category_fingerprint,nominee_type,nominator_employee_id,nominator_employee_no,nominator_name,nominator_appointment_id,nominator_fingerprint,individual_employee_id,individual_employee_no,individual_name,individual_appointment_id,individual_fingerprint,contribution_narrative,status,content_revision,record_version,created_by,created_at,updated_by,updated_at) VALUES('nom','A','cycle','cv',1,'fp','INDIVIDUAL',1,'E1','Nominator',1,'fp',2,'E2','Nominee',2,'fp','Work','SUBMITTED',1,0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");
   s.executeUpdate("INSERT INTO PUBLIC.rr_evaluation_case(id,agency_id,nomination_id,cycle_id,category_version_id,charter_version_id,charter_definition_version,charter_fingerprint,status,record_version,created_by,created_at,updated_by,updated_at) VALUES('eval','A','nom','cycle','cv','chv',1,'fp','FINAL_APPROVED',0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");
  }flyway(url,p,"46").migrate();try(var c=DriverManager.getConnection(url,"sa","");var r=c.createStatement().executeQuery("SELECT status FROM PUBLIC.rr_evaluation_case WHERE id='eval'")){r.next();assertThat(r.getString(1)).isEqualTo("FINAL_APPROVED");}try(var c=DriverManager.getConnection(url,"sa","");var r=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.rr_award_record")){r.next();assertThat(r.getLong(1)).isZero();}}
  finally{initial.clean();}
 }
 private Flyway flyway(String url,Map<String,String>p,String target){return Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(p).target(MigrationVersion.fromVersion(target)).cleanDisabled(false).load();}
}
